		return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
	case storepb.InboxMessage_MEMO_MENTION:
		payload := message.GetMemoMention()
		if payload == nil {
			return false
		}
		return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
	default:
